99	
100	static int i2ccmd_help(FAR struct i2ctool_s *i2ctool, int argc,
101	                       FAR char **argv)
102	{
103	  const struct cmdmap_s *ptr;
104	
105	  i2ctool_printf(i2ctool, "Usage: i2c <cmd> [arguments]\n");
106	  i2ctool_printf(i2ctool, "Where <cmd> is one of:\n\n");
107	  for (ptr = g_i2ccmds; ptr->cmd; ptr++)
108	    {
109	      if (ptr->usage)
110	        {
111	          i2ctool_printf(i2ctool, "  %s: %s %s\n",
112	                         ptr->desc, ptr->cmd, ptr->usage);
113	        }
114	      else
115	        {
116	          i2ctool_printf(i2ctool, "  %s: %s\n", ptr->desc, ptr->cmd);
117	        }
118	    }
119	
120	  i2ctool_printf(i2ctool,
121	                 "\nWhere common \"sticky\" OPTIONS include:\n");
122	  i2ctool_printf(i2ctool,
123	                 "  [-a addr] is the I2C device address (hex)."
124	                 "  Default: %02x Current: %02x\n",
125	                 CONFIG_I2CTOOL_MINADDR, i2ctool->addr);
126	  i2ctool_printf(i2ctool,
127	                 "  [-b bus] is the I2C bus number (decimal)."
128	                 "  Default: %d Current: %d\n",
129	                 CONFIG_I2CTOOL_MINBUS, i2ctool->bus);
130	  i2ctool_printf(i2ctool,
131	                 "  [-w width] is the data width (8 or 16 decimal)."
132	                 "  Default: 8 Current: %d\n",
133	                 i2ctool->width);
134	  i2ctool_printf(i2ctool,
135	                 "  [-s|n], send/don't send start between command and data."
136	                 "  Default: -n Current: %s\n",
137	                 i2ctool->start ? "-s" : "-n");
138	  i2ctool_printf(i2ctool,
139	                 "  [-i|j], Auto increment|don't increment regaddr on "
140	                 "repetitions."
141	                 "  Default: NO Current: %s\n",
142	                 i2ctool->autoincr ? "YES" : "NO");
143	  i2ctool_printf(i2ctool,
144	                 "  [-f freq] I2C frequency."
145	                 "  Default: %d Current: %" PRIu32 "\n",
146	                 CONFIG_I2CTOOL_DEFFREQ, i2ctool->freq);
147	
148	  i2ctool_printf(i2ctool, "\nSpecial non-sticky options:\n");
149	  i2ctool_printf(i2ctool,
150	                 "  [-r regaddr] is the I2C device register index (hex)."
151	                 "  Default: not used/sent\n");
152	  i2ctool_printf(
153	      i2ctool,
154	      "  [-z] instructs the 'dev' command to scan the I2C bus by sending "
155	      "zero-byte write headers (if the architecture supports it)\n");
156	
157	  i2ctool_printf(i2ctool, "\nNOTES:\n");
158	#ifndef CONFIG_DISABLE_ENVIRON
159	  i2ctool_printf(i2ctool, "o An environment variable like $PATH may be used "
160	                          "for any argument.\n");
161	#endif
162	  i2ctool_printf(i2ctool,
163	                 "o Arguments are \"sticky\". For example, once "
164	                 "the I2C address is\n");
165	  i2ctool_printf(i2ctool,
166	                 "  specified, that address will be re-used until "
167	                 "it is changed.\n");
168	  i2ctool_printf(i2ctool, "\nWARNING:\n");
169	  i2ctool_printf(i2ctool,
170	                 "o The I2C dev command may have bad side effects "
171	                 "on your I2C devices.\n");
172	  i2ctool_printf(i2ctool, "  Use only at your own risk.\n");
173	  return OK;
174	}
