187	/****************************************************************************
188	 * Name: i2c_execute
189	 ****************************************************************************/
190	
191	static int i2c_execute(FAR struct i2ctool_s *i2ctool, int argc,
192	                       FAR char *argv[])
193	{
194	  FAR const struct cmdmap_s *cmdmap;
195	  FAR const char            *cmd;
196	  cmd_t                     handler;
197	  int                       ret;
198	
199	  /* The form of argv is:
200	   *
201	   * argv[0]:      The command name.  This is argv[0] when the arguments
202	   *               are, finally, received by the command vtblr
203	   * argv[1]:      The beginning of argument (up to MAX_ARGUMENTS)
204	   * argv[argc]:   NULL terminating pointer
205	   */
206	
207	  /* See if the command is one that we understand */
208	
209	  cmd     = argv[0];
210	  handler = i2ccmd_unrecognized;
211	
212	  for (cmdmap = g_i2ccmds; cmdmap->cmd; cmdmap++)
213	    {
214	      if (strcmp(cmdmap->cmd, cmd) == 0)
215	        {
216	          handler = cmdmap->handler;
217	          break;
218	        }
219	    }
220	
221	  ret = handler(i2ctool, argc, argv);
222	  return ret;
223	}
