225	/****************************************************************************
226	 * Name: i2c_argument
227	 ****************************************************************************/
228	
229	static FAR char *i2c_argument(FAR struct i2ctool_s *i2ctool,
230	                              int argc, FAR char *argv[], FAR int *pindex)
231	{
232	  FAR char *arg;
233	  int  index = *pindex;
234	
235	  /* If we are at the end of the arguments with nothing, then return NULL */
236	
237	  if (index >= argc)
238	    {
239	      return NULL;
240	    }
241	
242	  /* Get the return parameter */
243	
244	  arg     = argv[index];
245	  *pindex = index + 1;
246	
247	#ifndef CONFIG_DISABLE_ENVIRON
248	  /* Check for references to environment variables */
249	
250	  if (arg[0] == '$')
251	    {
252	      /* Return the value of the environment variable with this name */
253	
254	      FAR char *value = getenv(arg + 1);
255	      if (value)
256	        {
257	          return value;
258	        }
259	      else
260	        {
261	          return (FAR char *)"";
262	        }
263	    }
264	#endif
265	
266	  /* Return the next argument. */
267	
268	  return arg;
269	}
