271	/****************************************************************************
272	 * Name: i2c_parse
273	 ****************************************************************************/
274	
275	static int i2c_parse(FAR struct i2ctool_s *i2ctool,
276	                     int argc, FAR char *argv[])
277	{
278	  FAR char *newargs[MAX_ARGUMENTS + 2];
279	  FAR char *cmd;
280	  int       nargs;
281	  int       index;
282	
283	  /* Parse out the command, skipping the first argument (the program name) */
284	
285	  index = 1;
286	  cmd = i2c_argument(i2ctool, argc, argv, &index);
287	
288	  /* Check if any command was provided */
289	
290	  if (!cmd)
291	    {
292	      /* An empty line is not an error and an unprocessed command cannot
293	       * generate an error, but neither should they change the last
294	       * command status.
295	       */
296	
297	      return i2ccmd_help(i2ctool, 0, NULL);
298	    }
299	
300	  /* Parse all of the arguments following the command name. */
301	
302	  newargs[0] = cmd;
303	  for (nargs = 1; nargs <= MAX_ARGUMENTS; nargs++)
304	    {
305	      newargs[nargs] = i2c_argument(i2ctool, argc, argv, &index);
306	      if (!newargs[nargs])
307	        {
308	          break;
309	        }
310	    }
311	
312	  newargs[nargs] = NULL;
313	
314	  /* Then execute the command */
315	
316	  return i2c_execute(i2ctool, nargs, newargs);
317	}
