322	
323	static inline int i2c_setup(FAR struct i2ctool_s *i2ctool)
324	{
325	  /* Initialize the output stream */
326	
327	#ifdef CONFIG_I2CTOOL_OUTDEV
328	  i2ctool->ss_outfd = open(CONFIG_I2CTOOL_OUTDEV, O_WRONLY);
329	  if (i2ctool->ss_outfd < 0)
330	    {
331	      fprintf(stderr, g_i2ccmdfailed, "open", errno);
332	      return ERROR;
333	    }
334	
335	  /* Create a standard C stream on the console device */
336	
337	  i2ctool->ss_outstream = fdopen(i2ctool->ss_outfd, "w");
338	  if (!i2ctool->ss_outstream)
339	    {
340	      fprintf(stderr, g_i2ccmdfailed, "fdopen", errno);
341	      return ERROR;
342	    }
343	#endif
344	
345	  return OK;
346	}
