369	/****************************************************************************
370	 * Name: i2c_main
371	 ****************************************************************************/
372	
373	int main(int argc, FAR char *argv[])
374	{
375	  /* Verify settings */
376	
377	  if (g_i2ctool.bus < CONFIG_I2CTOOL_MINBUS ||
378	      g_i2ctool.bus > CONFIG_I2CTOOL_MAXBUS)
379	    {
380	      g_i2ctool.bus = CONFIG_I2CTOOL_MINBUS;
381	    }
382	
383	  if (g_i2ctool.addr < CONFIG_I2CTOOL_MINADDR ||
384	      g_i2ctool.addr > CONFIG_I2CTOOL_MAXADDR)
385	    {
386	      g_i2ctool.addr = CONFIG_I2CTOOL_MINADDR;
387	    }
388	
389	  if (g_i2ctool.regaddr > CONFIG_I2CTOOL_MAXREGADDR)
390	    {
391	      g_i2ctool.regaddr = 0;
392	    }
393	
394	  if (g_i2ctool.width != 8 && g_i2ctool.width != 16)
395	    {
396	      g_i2ctool.width = 8;
397	    }
398	
399	  if (g_i2ctool.freq == 0)
400	    {
401	      g_i2ctool.freq = CONFIG_I2CTOOL_DEFFREQ;
402	    }
403	
404	  g_i2ctool.hasregindx = false;
405	  g_i2ctool.zerowrite = false;
406	
407	  /* Parse and process the command line */
408	
409	  i2c_setup(&g_i2ctool);
410	  i2c_parse(&g_i2ctool, argc, argv);
411	
412	  i2ctool_flush(&g_i2ctool);
413	  i2c_teardown(&g_i2ctool);
414	  return OK;
415	}
