39	 * Name: i2ccmd_get
40	 ****************************************************************************/
41	
42	int i2ccmd_get(FAR struct i2ctool_s *i2ctool, int argc, FAR char **argv)
43	{
44	  FAR char *ptr;
45	  uint16_t result;
46	  uint8_t regaddr;
47	  long repetitions;
48	  int nargs;
49	  int argndx;
50	  int ret;
51	  int fd;
52	  int i;
53	
54	  /* Parse any command line arguments */
55	
56	  for (argndx = 1; argndx < argc; )
57	    {
58	      /* Break out of the look when the last option has been parsed */
59	
60	      ptr = argv[argndx];
61	      if (*ptr != '-')
62	        {
63	          break;
64	        }
65	
66	      /* Otherwise, check for common options */
67	
68	      nargs = i2ctool_common_args(i2ctool, &argv[argndx]);
69	      if (nargs < 0)
70	        {
71	          return ERROR;
72	        }
73	
74	      argndx += nargs;
75	    }
76	
77	  /* There may be one more thing on the command line:  The repetition
78	   * count.
79	   */
80	
81	  repetitions = 1;
82	  if (argndx < argc)
83	    {
84	      repetitions = strtol(argv[argndx], NULL, 16);
85	      if (repetitions < 1)
86	        {
87	          i2ctool_printf(i2ctool, g_i2cargrange, argv[0]);
88	          return ERROR;
89	        }
90	
91	      argndx++;
92	    }
93	
94	  if (argndx != argc)
95	    {
96	      i2ctool_printf(i2ctool, g_i2ctoomanyargs, argv[0]);
97	      return ERROR;
98	    }
99	
100	  /* Get a handle to the I2C bus */
101	
102	  fd = i2cdev_open(i2ctool->bus);
103	  if (fd < 0)
104	    {
105	      i2ctool_printf(i2ctool, "Failed to get bus %d\n", i2ctool->bus);
106	      return ERROR;
107	    }
108	
109	  /* Loop for the requested number of repetitions */
110	
111	  regaddr = i2ctool->regaddr;
112	  ret = OK;
113	
114	  for (i = 0; i < repetitions; i++)
115	    {
116	      /* Read from the I2C bus */
117	
118	      ret = i2ctool_get(i2ctool, fd, regaddr, &result);
119	
120	      /* Display the result */
121	
122	      if (ret == OK)
123	        {
124	          i2ctool_printf(i2ctool,
125	                         "READ Bus: %d Addr: %02x Subaddr: %02x Value: ",
126	                         i2ctool->bus, i2ctool->addr, regaddr);
127	
128	          if (i2ctool->width == 8)
129	            {
130	              i2ctool_printf(i2ctool, "%02x\n", result);
131	            }
132	          else
133	            {
134	              i2ctool_printf(i2ctool, "%04x\n", result);
135	            }
136	        }
137	      else
138	        {
139	          i2ctool_printf(i2ctool, g_i2cxfrerror, argv[0], -ret);
140	          break;
141	        }
142	
143	      /* Auto-increment the address if so configured */
144	
145	      if (i2ctool->autoincr)
146	        {
147	          regaddr++;
148	        }
149	    }
150	
151	  close(fd);
152	  return ret;
153	}
