155	/****************************************************************************
156	 * Name: i2ctool_get
157	 ****************************************************************************/
158	
159	int i2ctool_get(FAR struct i2ctool_s *i2ctool, int fd, uint8_t regaddr,
160	                FAR uint16_t *result)
161	{
162	  struct i2c_msg_s msg[2];
163	  int ret;
164	  union
165	  {
166	    uint16_t data16;
167	    uint8_t  data8;
168	  } u;
169	
170	  /* Set up data structures */
171	
172	  if (i2ctool->hasregindx)
173	    {
174	      msg[0].frequency = i2ctool->freq;
175	      msg[0].addr      = i2ctool->addr;
176	      msg[0].flags     = I2C_M_NOSTOP;
177	      msg[0].buffer    = &regaddr;
178	      msg[0].length    = 1;
179	
180	      msg[1].frequency = i2ctool->freq;
181	      msg[1].addr      = i2ctool->addr;
182	      msg[1].flags     = I2C_M_READ;
183	
184	      if (i2ctool->width == 8)
185	        {
186	          msg[1].buffer = &u.data8;
187	          msg[1].length = 1;
188	        }
189	      else
190	        {
191	          msg[1].buffer = (uint8_t *)&u.data16;
192	          msg[1].length = 2;
193	        }
194	
195	      if (i2ctool->start)
196	        {
197	          ret = i2cdev_transfer(fd, &msg[0], 1);
198	          if (ret == OK)
199	            {
200	              ret = i2cdev_transfer(fd, &msg[1], 1);
201	            }
202	        }
203	      else
204	        {
205	          ret = i2cdev_transfer(fd, msg, 2);
206	        }
207	    }
208	  else
209	    {
210	      /* no register index "-r" has been specified so
211	       * we do a pure read (no write of index)
212	       */
213	
214	      msg[0].frequency = i2ctool->freq;
215	      msg[0].addr      = i2ctool->addr;
216	      msg[0].flags     = I2C_M_READ;
217	
218	      if (i2ctool->width == 8)
219	        {
220	          msg[0].buffer = &u.data8;
221	          msg[0].length = 1;
222	        }
223	      else
224	        {
225	          msg[0].buffer = (uint8_t *)&u.data16;
226	          msg[0].length = 2;
227	        }
228	
